/**
 * Build-time knowledgebase vault.
 *
 * The vault is discovered from `knowledgebase/**\/*.md` with `fs`, parsed
 * with `gray-matter`, and turned into a tree of folders and notes plus the
 * lookup maps and backlink graph the markdown pipeline needs. There is no
 * runtime vault and no page file per note: routes are generated by
 * `getStaticPaths()` from this data.
 */

import fs from 'node:fs';
import path from 'node:path';
import matter from 'gray-matter';
import GithubSlugger from 'github-slugger';
import {
  formatOrder,
  getOrder,
  slugify,
  stripOrderPrefix,
} from './slug';

export const VAULT_ROOT_DIR = path.resolve(process.cwd(), 'knowledgebase');
export const VAULT_ROUTE = '/knowledgebase/';

export interface VaultHeading {
  text: string;
  id: string;
  level: number;
}

interface VaultEntryBase {
  /** Full path relative to the repository root. */
  relPath: string;
  /** Path segments relative to the vault root, without file extension. */
  segments: string[];
  /** Folder name or note basename (without `.md`). */
  name: string;
  title: string;
  displayTitle: string;
  order: number | null;
  orderLabel: string | null;
  slug: string;
  route: string;
  parentRoute: string;
}

export interface VaultFolder extends VaultEntryBase {
  type: 'folder';
  children: VaultEntry[];
}

export interface VaultNote extends VaultEntryBase {
  type: 'note';
  /** Basename without `.md`, including the ordering prefix. */
  basename: string;
  /** Raw frontmatter title, or null when the note has no frontmatter title. */
  frontmatterTitle: string | null;
  tags: string[];
  body: string;
  headings: VaultHeading[];
}

export type VaultEntry = VaultFolder | VaultNote;

export interface VaultBacklink {
  route: string;
  title: string;
  displayTitle: string;
  order: number | null;
}

export interface Vault {
  root: VaultFolder;
  entries: VaultEntry[];
  folders: VaultFolder[];
  notes: VaultNote[];
  byRoute: Map<string, VaultEntry>;
  byFullBasename: Map<string, VaultEntry>;
  byFullBasenameLower: Map<string, VaultEntry>;
  byStrippedTitle: Map<string, VaultEntry>;
  byStrippedSlug: Map<string, VaultEntry>;
  byRelPath: Map<string, VaultEntry>;
  byRelPathLower: Map<string, VaultEntry>;
  byRelPathSlug: Map<string, VaultEntry>;
  backlinks: Map<string, VaultBacklink[]>;
}

export interface WikilinkParts {
  raw: string;
  inner: string;
  embed: boolean;
  target: string;
  heading: string | null;
  alias: string | null;
}

export interface MissingLink {
  source: string;
  sourceRoute: string;
  target: string;
  alias: string | null;
  heading: string | null;
  reason: 'missing-note' | 'missing-heading';
}

const WIKILINK_RE = /!?\[\[([^[\]\n]+?)\]\]/g;

/** Parse the inside of a wikilink (`Note#Heading|Alias`). */
export function parseWikilinkInner(
  inner: string,
  embed = false,
): WikilinkParts | null {
  const cleaned = inner.replace(/\\\|/g, '|').trim();
  if (!cleaned) return null;

  const pipeAt = cleaned.indexOf('|');
  const left = pipeAt === -1 ? cleaned : cleaned.slice(0, pipeAt);
  const alias =
    pipeAt === -1 ? null : cleaned.slice(pipeAt + 1).trim() || null;

  const hashAt = left.indexOf('#');
  const target = (hashAt === -1 ? left : left.slice(0, hashAt)).trim();
  const heading =
    hashAt === -1 ? null : left.slice(hashAt + 1).trim() || null;

  if (!target && !heading) return null;
  return {
    raw: `${embed ? '!' : ''}[[${inner}]]`,
    inner,
    embed,
    target,
    heading,
    alias,
  };
}

/** All wikilinks in a raw markdown body, in document order. */
export function extractWikilinks(body: string): WikilinkParts[] {
  const links: WikilinkParts[] = [];
  for (const match of body.matchAll(WIKILINK_RE)) {
    const parsed = parseWikilinkInner(match[1], match[0].startsWith('!'));
    if (parsed) links.push(parsed);
  }
  return links;
}

/** Slug an already-plain heading, matching rehype-slug's GithubSlugger. */
export function slugifyHeading(text: string): string {
  return new GithubSlugger().slug(text);
}

function inlineHeadingText(markdown: string): string {
  let text = markdown;

  text = text.replace(/!?\[\[([^[\]\n]+?)\]\]/g, (_raw, inner: string) => {
    const link = parseWikilinkInner(inner);
    if (!link) return '';
    return link.alias ?? (stripOrderPrefix(link.target) || link.heading || '');
  });
  text = text.replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1');
  text = text.replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
  text = text.replace(/<((?:https?:\/\/|mailto:)[^>]+)>/g, '$1');
  text = text.replace(/<\/?[^>]+>/g, '');
  text = text.replace(/(`+)(.*?)\1/g, '$2');
  text = text.replace(/[*_~]+/g, '');
  text = text.replace(/\\([\\`*{}[\]()#+\-.!_|>])/g, '$1');
  return text.trim();
}

function extractHeadings(body: string): VaultHeading[] {
  const slugger = new GithubSlugger();
  const headings: VaultHeading[] = [];
  let fence: string | null = null;

  for (const line of body.split(/\r?\n/)) {
    if (/^\s*(```|~~~)/.test(line)) {
      const marker = line.trim().slice(0, 3);
      if (fence === null) fence = marker;
      else if (fence === marker) fence = null;
      continue;
    }
    if (fence !== null) continue;

    const match = /^(#{1,6})\s+(.+?)\s*#*\s*$/.exec(line);
    if (!match) continue;

    const text = inlineHeadingText(match[2]);
    if (!text) continue;
    headings.push({
      text,
      id: slugger.slug(text),
      level: match[1].length,
    });
  }

  return headings;
}

function isMarkdownFile(name: string): boolean {
  return name.toLowerCase().endsWith('.md') && !name.startsWith('.');
}

function normaliseTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value
      .map((tag) => String(tag).trim().replace(/^#/, ''))
      .filter(Boolean);
  }
  if (typeof value === 'string') {
    return value
      .split(/[,\s]+/)
      .map((tag) => tag.trim().replace(/^#/, ''))
      .filter(Boolean);
  }
  return [];
}

function compareEntries(a: VaultEntry, b: VaultEntry): number {
  if (a.type !== b.type) return a.type === 'folder' ? -1 : 1;

  if (a.order !== null && b.order !== null && a.order !== b.order) {
    return a.order - b.order;
  }
  if (a.order !== null && b.order === null) return -1;
  if (a.order === null && b.order !== null) return 1;

  return a.displayTitle.localeCompare(b.displayTitle, 'en', {
    numeric: true,
    sensitivity: 'base',
  });
}

function routeFor(parentRoute: string, slug: string): string {
  return `${parentRoute}${slug}/`;
}

interface BuildState {
  folders: VaultFolder[];
  notes: VaultNote[];
  duplicateRoutes: string[];
}

function walkFolder(
  dir: string,
  relativeSegments: string[],
  parentRoute: string,
  state: BuildState,
): VaultFolder | null {
  const dirEntries = fs.readdirSync(dir, { withFileTypes: true });
  const name = relativeSegments[relativeSegments.length - 1] ?? 'knowledgebase';
  const slug = relativeSegments.length === 0 ? '' : slugify(name);
  const route =
    relativeSegments.length === 0 ? VAULT_ROUTE : routeFor(parentRoute, slug);

  const folder: VaultFolder = {
    type: 'folder',
    relPath: relativeSegments.join('/'),
    segments: relativeSegments,
    name,
    title: name,
    displayTitle: relativeSegments.length === 0 ? 'Knowledgebase' : name,
    order: relativeSegments.length === 0 ? null : getOrder(name),
    orderLabel: relativeSegments.length === 0 ? null : formatOrder(getOrder(name)),
    slug,
    route,
    parentRoute,
    children: [],
  };

  for (const entry of dirEntries) {
    if (entry.name.startsWith('.') || entry.name === '.DS_Store') continue;

    const absolute = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      const child = walkFolder(
        absolute,
        [...relativeSegments, entry.name],
        route,
        state,
      );
      if (child) folder.children.push(child);
      continue;
    }

    if (!entry.isFile() || !isMarkdownFile(entry.name)) continue;

    const raw = fs.readFileSync(absolute, 'utf8');
    const parsed = matter(raw);
    const basename = entry.name.replace(/\.md$/i, '');
    const frontmatterTitle =
      typeof parsed.data.title === 'string' && parsed.data.title.trim()
        ? parsed.data.title.trim()
        : null;
    const title = frontmatterTitle ?? basename;
    const order = getOrder(basename) ?? getOrder(title);

    const note: VaultNote = {
      type: 'note',
      relPath: path
        .relative(VAULT_ROOT_DIR, absolute)
        .split(path.sep)
        .join('/'),
      segments: [...relativeSegments, basename],
      name: basename,
      basename,
      title,
      displayTitle: stripOrderPrefix(title),
      order,
      orderLabel: formatOrder(order),
      slug: slugify(basename),
      route: routeFor(route, slugify(basename)),
      parentRoute: route,
      frontmatterTitle,
      tags: normaliseTags(parsed.data.tags),
      body: parsed.content,
      headings: extractHeadings(parsed.content),
    };

    folder.children.push(note);
    state.notes.push(note);
  }

  if (relativeSegments.length > 0 && folder.children.length === 0) {
    return null;
  }

  const seenSlugs = new Map<string, VaultEntry>();
  for (const child of folder.children) {
    const duplicate = seenSlugs.get(child.slug);
    if (duplicate) {
      state.duplicateRoutes.push(
        `${folder.route} -> "${duplicate.name}" and "${child.name}" both slugify to "${child.slug}"`,
      );
    } else {
      seenSlugs.set(child.slug, child);
    }
  }

  folder.children.sort(compareEntries);
  if (relativeSegments.length > 0) state.folders.push(folder);
  return folder;
}

function addToMap(
  map: Map<string, VaultEntry>,
  key: string,
  entry: VaultEntry,
): void {
  if (!key || map.has(key)) return;
  map.set(key, entry);
}

function buildMaps(vault: Vault): void {
  const all = [vault.root, ...vault.folders, ...vault.notes];

  for (const entry of all) {
    const fullName = entry.type === 'note' ? entry.basename : entry.name;
    const stripped = stripOrderPrefix(fullName);
    const relPath = entry.segments.join('/');

    addToMap(vault.byFullBasename, fullName, entry);
    addToMap(vault.byFullBasenameLower, fullName.toLowerCase(), entry);
    addToMap(vault.byStrippedTitle, stripped.toLowerCase(), entry);
    addToMap(vault.byStrippedSlug, slugify(stripped), entry);
    addToMap(vault.byRelPath, relPath, entry);
    addToMap(vault.byRelPathLower, relPath.toLowerCase(), entry);
    addToMap(
      vault.byRelPathSlug,
      entry.segments.map((segment) => slugify(segment)).join('/'),
      entry,
    );
    addToMap(vault.byRoute, entry.route, entry);
    if (entry.route !== VAULT_ROUTE) {
      addToMap(vault.byRoute, entry.route.replace(/\/$/, ''), entry);
    }
  }
}

/** Resolve a wikilink target by basename, stripped basename, path or route. */
export function resolveEntry(
  vault: Pick<
    Vault,
    | 'byFullBasename'
    | 'byFullBasenameLower'
    | 'byStrippedTitle'
    | 'byStrippedSlug'
    | 'byRelPath'
    | 'byRelPathLower'
    | 'byRelPathSlug'
    | 'byRoute'
  >,
  rawTarget: string,
): VaultEntry | null {
  const target = rawTarget
    .trim()
    .replace(/^<|>$/g, '')
    .replace(/^\.\//, '')
    .replace(/\.md$/i, '')
    .replace(/\\/g, '/')
    .replace(/\/+$/, '');

  if (!target) return null;

  const candidates: Array<[Map<string, VaultEntry>, string]> = [
    [vault.byFullBasename, target],
    [vault.byRelPath, target],
    [vault.byRoute, target.startsWith('/') ? `${target}/` : target],
    [vault.byRoute, target],
    [vault.byFullBasenameLower, target.toLowerCase()],
    [vault.byRelPathLower, target.toLowerCase()],
  ];

  for (const [map, key] of candidates) {
    const found = map.get(key);
    if (found) return found;
  }

  const slugPath = target
    .split('/')
    .filter(Boolean)
    .map((segment) => slugify(segment))
    .join('/');

  return (
    vault.byStrippedSlug.get(slugify(target)) ??
    vault.byStrippedTitle.get(stripOrderPrefix(target).toLowerCase()) ??
    vault.byRelPathSlug.get(slugPath) ??
    (target.startsWith('/')
      ? vault.byRoute.get(`${slugPath}/`)
      : undefined) ??
    null
  );
}

/** Find the heading id a `[[Note#Heading]]` link points at. */
export function resolveHeading(
  note: VaultNote,
  heading: string,
): VaultHeading | null {
  const wantedText = heading.trim().toLowerCase();
  const wantedId = slugifyHeading(heading);

  return (
    note.headings.find((candidate) => candidate.text.toLowerCase() === wantedText) ??
    note.headings.find((candidate) => candidate.id === wantedId) ??
    null
  );
}

function buildBacklinks(vault: Vault): void {
  for (const note of vault.notes) {
    const seen = new Set<string>();

    for (const link of extractWikilinks(note.body)) {
      if (!link.target) continue;
      const target = resolveEntry(vault, link.target);
      if (!target || target.type !== 'note') continue;
      if (target.route === note.route || seen.has(target.route)) continue;

      seen.add(target.route);
      const list = vault.backlinks.get(target.route) ?? [];
      list.push({
        route: note.route,
        title: note.title,
        displayTitle: note.displayTitle,
        order: note.order,
      });
      vault.backlinks.set(target.route, list);
    }
  }

  for (const list of vault.backlinks.values()) {
    list.sort((a, b) => {
      if (a.order !== null && b.order !== null && a.order !== b.order) {
        return a.order - b.order;
      }
      if (a.order !== null && b.order === null) return -1;
      if (a.order === null && b.order !== null) return 1;
      return a.displayTitle.localeCompare(b.displayTitle, 'en', {
        numeric: true,
        sensitivity: 'base',
      });
    });
  }
}

let cachedVault: Vault | null = null;

/** Build (and cache) the vault. Throws on duplicate generated routes. */
export function buildVault(rootDir = VAULT_ROOT_DIR): Vault {
  if (cachedVault && rootDir === VAULT_ROOT_DIR) return cachedVault;

  if (!fs.existsSync(rootDir)) {
    throw new Error(`knowledgebase: vault root not found at ${rootDir}`);
  }

  const state: BuildState = { folders: [], notes: [], duplicateRoutes: [] };
  const root = walkFolder(rootDir, [], VAULT_ROUTE, state);
  if (!root) throw new Error('knowledgebase: vault root could not be built');

  if (state.duplicateRoutes.length > 0) {
    throw new Error(
      `knowledgebase: duplicate routes/slugs:\n${state.duplicateRoutes
        .map((line) => `  - ${line}`)
        .join('\n')}`,
    );
  }

  const entries: VaultEntry[] = [...state.folders, ...state.notes];
  const vault: Vault = {
    root,
    entries,
    folders: state.folders,
    notes: state.notes,
    byRoute: new Map(),
    byFullBasename: new Map(),
    byFullBasenameLower: new Map(),
    byStrippedTitle: new Map(),
    byStrippedSlug: new Map(),
    byRelPath: new Map(),
    byRelPathLower: new Map(),
    byRelPathSlug: new Map(),
    backlinks: new Map(),
  };

  buildMaps(vault);
  buildBacklinks(vault);

  if (rootDir === VAULT_ROOT_DIR) cachedVault = vault;
  return vault;
}

/** The vault singleton used by pages and components. */
export const vault = buildVault();

/** Route generated by `getStaticPaths()`: no leading/trailing slash. */
export function routeParam(entry: VaultEntry): string {
  return entry.route
    .replace(/^\/knowledgebase\/?/, '')
    .replace(/\/$/, '');
}

/** Trace route -> ancestors, used for breadcrumbs. */
export function breadcrumbFor(
  vaultData: Vault,
  entry: VaultEntry,
): VaultEntry[] {
  const chain: VaultEntry[] = [];
  let current: VaultEntry | undefined = entry;

  while (current) {
    chain.unshift(current);
    if (current.route === VAULT_ROUTE) break;
    current = vaultData.byRoute.get(current.parentRoute);
  }

  return chain;
}
